    let x = 0;
    if (st.length) x += ti === 0 ? z.pairOv + rowsOf(st.map(i => z.h[i]), z.two) : st.reduce((a, i) => a + z.h[i], 0) + (ti === 1 ? z.pad : 0);
    if (br.length) x += z.briefOv + br.reduce((a, i) => a + z.h[i], 0);
