    const by = targets.map(ti => units.map((u, i) => i).filter(i => where[i] === ti));
    const a = baseA + tailH(0, by[0]), b = by[1].length ? topB + tailH(1, by[1]) : null, c = baseC + (ncols >= 3 ? tailH(2, by[2]) : 0);
