    const present = CFG.sections.map(x => ({ x, el: document.getElementById(x.id) })).filter(o => o.el && !o.el.hidden)
      .sort((a, b) => (a.el.compareDocumentPosition(b.el) & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1)).map(o => o.x);
